func uniqueXorTriplets(nums []int) int {
	maxNum := 0
	for _, num := range nums {
		if num > maxNum {
			maxNum = num
		}
	}

	limit := 1
	for limit <= maxNum {
		limit <<= 1
	}

	exists := make([]bool, limit)
	values := []int{}
	for _, num := range nums {
		if !exists[num] {
			exists[num] = true
			values = append(values, num)
		}
	}

	pairs := make([]bool, limit)
	for _, i := range values {
		for _, j := range values {
			pairs[i^j] = true
		}
	}

	triplets := make([]bool, limit)
	for _, i := range values {
		for j, ok := range pairs {
			if ok {
				triplets[i^j] = true
			}
		}
	}

	count := 0
	for _, ok := range triplets {
		if ok {
			count++
		}
	}
	return count
}
